import { readFileSync } from 'node:fs'

class Fail extends Error {}

const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function fail(line, reason) {
  throw new Fail(`error: line ${line}: ${reason}`)
}

function uint(line, field, text, least) {
  if (!UINT.test(text) || BigInt(text) < BigInt(least)) {
    fail(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(text)
}

class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }
  advance(key, tick) {
    let s = this.states.get(key)
    if (!s) {
      // tokens are stored scaled by `per`, so fractions stay exact
      s = { num: this.capacity * this.per, last: tick }
      this.states.set(key, s)
    }
    const max = this.capacity * this.per
    s.num += this.refill * (tick - s.last)
    if (s.num > max) s.num = max
    s.last = tick
  }
  allows(key) {
    return this.states.get(key).num >= this.per
  }
  record(key) {
    this.states.get(key).num -= this.per
  }
}

class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }
  advance(key, tick) {
    let s = this.states.get(key)
    if (!s) {
      s = []
      this.states.set(key, s)
    }
    const cut = tick - this.span
    while (s.length && s[0] <= cut) s.shift()
  }
  allows(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }
  record(key, tick) {
    this.states.get(key).push(tick)
  }
}

function run(mode, text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

  lines.forEach((raw, i) => {
    const n = i + 1
    const t = raw.trim()
    if (t === '' || t.startsWith('#')) return
    const f = t.split(/\s+/)
    const word = f[0]
    const late = () => {
      if (started) fail(n, 'declarations must come before the first event')
    }
    if (word === 'bucket') {
      if (f.length !== 5) fail(n, 'expected bucket <name> <capacity> <refill> <per>')
      if (!NAME.test(f[1])) fail(n, `invalid policy name ${f[1]}`)
      const cap = uint(n, 'capacity', f[2], 1)
      const refill = uint(n, 'refill', f[3], 0)
      const per = uint(n, 'per', f[4], 1)
      late()
      if (policies.has(f[1])) fail(n, `policy ${f[1]} is declared twice`)
      policies.set(f[1], new Bucket(f[1], cap, refill, per))
    } else if (word === 'window') {
      if (f.length !== 4) fail(n, 'expected window <name> <limit> <span>')
      if (!NAME.test(f[1])) fail(n, `invalid policy name ${f[1]}`)
      const limit = uint(n, 'limit', f[2], 0)
      const span = uint(n, 'span', f[3], 1)
      late()
      if (policies.has(f[1])) fail(n, `policy ${f[1]} is declared twice`)
      policies.set(f[1], new Window(f[1], limit, span))
    } else if (word === 'route') {
      if (f.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (!NAME.test(f[1])) fail(n, `invalid route prefix ${f[1]}`)
      late()
      if (routes.has(f[1])) fail(n, `prefix ${f[1]} is routed twice`)
      const list = f.slice(2).map((p) => {
        if (!policies.has(p)) fail(n, `unknown policy ${p}`)
        return policies.get(p)
      })
      routes.set(f[1], list)
    } else if (word === 'event') {
      if (f.length !== 3) fail(n, 'expected event <tick> <key>')
      if (!NAME.test(f[2])) fail(n, `invalid key ${f[2]}`)
      const tick = uint(n, 'tick', f[1], 0)
      if (prev !== null && tick < prev) fail(n, `tick ${tick} is before tick ${prev}`)
      started = true
      prev = tick
      const key = f[2]
      let best = null
      for (const p of routes.keys()) {
        if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
      }
      let refused = null
      if (best !== null) {
        const list = routes.get(best)
        for (const p of list) p.advance(key, tick)
        for (const p of list) {
          if (!p.allows(key)) {
            refused = p
            break
          }
        }
        if (!refused) for (const p of list) p.record(key, tick)
      }
      const st = stats.get(key) || { a: 0, d: 0 }
      stats.set(key, st)
      if (refused) {
        st.d++
        denied++
        out.push(`${tick} ${key} deny ${refused.name}`)
      } else {
        st.a++
        allowed++
        out.push(`${tick} ${key} allow`)
      }
    } else {
      fail(n, `unknown directive ${word}`)
    }
  })

  if (mode === 'summary') {
    const res = []
    for (const k of [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
      res.push(`${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
    }
    res.push(`total allowed=${allowed} denied=${denied}`)
    return res
  }
  return out
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
let lines
try {
  lines = run(args[0], readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(2)
}
process.stdout.write(lines.map((l) => l + '\n').join(''))
